			int count;
		}

		Ping() {
			count = 0;
		}

		msgsrv initial() {
			// corresponds to StartMessage being sent to ping in main
			StartMessage();
		}

		msgsrv StartMessage() {
			// println("Ping started the game!")
			pong.PingMessage();
		}

		msgsrv PongMessage() {
			count = count + 1;
